import { Model } from './model.js';

// Core view. Feature modules (orbs, virtualFolders, experience, contact) extend it with Object.assign.
export const View = {
  els: {},
  optionIndex: 0,

  init() {
    this.els = {
      screens: [...document.querySelectorAll(".screen")],
