body {
  height: 100vh;
  min-height: 100vh;
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background-color: var(--ink);
  background-image: linear-gradient(var(--grid-line) 1px, transparent 1px), linear-gradient(90deg, var(--grid-line) 1px, transparent 1px);
  background-size: 48px 48px;
  color: var(--paper);
}
html, body { min-height: 100vh; }
.page-shell {
  position: relative;
  width: min(1740px, calc(100vw - 48px));
  height: min(96vh, calc(100svh - 32px));
  max-height: 1120px;
  min-height: 520px;
  display: flex;
  flex-direction: column;
  padding: 0 32px;
  border: 1px solid var(--line);
  box-shadow: 0 16px 60px rgba(0, 0, 0, 0.65);
  background: rgba(9, 11, 10, .96);
}
.topbar { min-height: 72px; flex: 0 0 auto; }
.wordmark { padding: 0; border: 0; background: transparent; cursor: pointer; }
.system-status { margin-left: auto; white-space: nowrap; }
.status-divider { color: var(--green-dim); }
.site-nav { margin-left: 8px; gap: 17px; }
.site-nav button { padding: 8px 0; border: 0; background: transparent; color: #aeb5ad; cursor: pointer; font: 10px var(--mono); transition: color .2s ease; }
.site-nav button:hover, .site-nav button[aria-current="page"] { color: var(--green); }
.site-nav button[aria-current="page"]::after { display: block; height: 1px; margin-top: 5px; background: var(--green); content: ""; }
#stage { position: relative; flex: 1 1 auto; min-height: 0; overflow: hidden; border: 1px solid var(--line); background: rgba(9, 11, 10, .88); }
.screen { position: absolute; inset: 0; display: none; overflow-y: auto; overscroll-behavior: contain; padding: clamp(24px, 4vw, 54px); scrollbar-color: var(--green-dim) transparent; scrollbar-width: thin; }
.screen.is-active {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: stretch;
  gap: 22px;
  animation: screen-enter .24s ease both;
}
.screen::-webkit-scrollbar { width: 6px; }
.screen::-webkit-scrollbar-thumb { background: var(--green-dim); }
@keyframes screen-enter { from { opacity: .3; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.home-screen.is-active { display: grid; grid-template-columns: minmax(0, 1fr) 210px; align-items: center; gap: 36px; }
.home-content { max-width: 820px; }
.hero-topline { display: flex; flex-wrap: wrap; gap: 8px 22px; margin-bottom: 48px; color: var(--muted); font-size: 9px; }
.hero-topline span:first-child { color: var(--green); }
.home-screen .eyebrow { margin-bottom: 12px; }
.home-screen h1 { margin: 0 0 13px; font-size: clamp(58px, 9vw, 108px); }
.hero-role { margin: 17px 0 14px; color: var(--green); font-size: 13px; }
.hero-role span { color: var(--muted); }
.hero-rule { width: min(100%, 570px); height: 1px; background: var(--line); }
.intro { max-width: 700px; margin: 19px 0 25px; color: #bbc1ba; font-size: 13px; line-height: 1.85; }
.prompt-mark { margin-right: 7px; color: var(--green); }
.home-menu { display: grid; width: min(100%, 700px); border-top: 1px solid var(--line); }
.menu-item { min-height: 45px; display: grid; grid-template-columns: 48px 1fr 24px; align-items: center; gap: 10px; padding: 0 12px; border: 0; border-bottom: 1px solid var(--line); background: transparent; color: #d1d6d0; cursor: pointer; text-align: left; font: 500 12px var(--mono); transition: background .18s ease, color .18s ease; }
.menu-item.is-selected { background: rgba(157, 242, 173, .07); color: var(--green); }
.menu-index { color: var(--green-dim); font-size: 10px; }
.menu-arrow { justify-self: end; color: var(--green); font-size: 16px; }
.home-readout { align-self: end; margin-bottom: 4px; padding: 0 0 6px 18px; border-left: 1px solid var(--line); }
.readout-label { color: var(--muted); font-size: 9px; letter-spacing: .04em; }
.home-readout strong { display: block; margin: 13px 0 35px; font: 500 24px/1.3 var(--display); }
.home-readout strong span { color: var(--green); }
.aside-coordinate { display: flex; flex-direction: column; gap: 5px; margin-top: 16px; padding-top: 11px; border-top: 1px solid var(--line); }
.aside-coordinate span:first-child { color: var(--muted); font-size: 9px; }
.aside-coordinate span:last-child { color: var(--cyan); font-size: 9px; }
.page-controls { min-height: 60px; display: flex; flex: 0 0 auto; align-items: center; gap: 22px; border-top: 1px solid var(--line); }
.pager-button { display: inline-flex; align-items: center; gap: 8px; padding: 8px 0; border: 0; background: transparent; color: var(--green); cursor: pointer; font: 10px var(--mono); }
.pager-button:disabled { opacity: .35; }
.page-progress { display: flex; align-items: center; gap: 12px; color: var(--muted); font-size: 9px; }
#page-dots { display: flex; gap: 5px; }
#page-dots button { width: 15px; height: 3px; padding: 0; border: 0; background: var(--line); cursor: pointer; }
#page-dots button.is-active { background: var(--green); }
.keyboard-hint { display: flex; align-items: center; gap: 5px; margin-left: auto; color: var(--muted); font-size: 8px; }
.keyboard-hint kbd { min-width: 18px; padding: 3px 4px; border: 1px solid var(--line); color: var(--paper); font: 8px var(--mono); text-align: center; }
.hint-divider { padding: 0 4px; color: var(--green-dim); }
.screen-heading { margin-bottom: 28px; }
