  const titleEl = document.querySelector('#screen-about [data-i18n="aboutTitle"]');
  const quoteEl = document.querySelector('#screen-about [data-i18n="quote"]');

  if (this._titleTypingTimer) window.clearInterval(this._titleTypingTimer);
