  if (titleEl) {
    const titleHtml = Model.translations[Model.locale].aboutTitle;
    const tempDiv = document.createElement("div");
    tempDiv.innerHTML = titleHtml;
    const titleText = tempDiv.textContent || titleHtml;
    titleEl.textContent = "";
    let i = 0;
    this._titleTypingTimer = window.setInterval(() => {
      if (i < titleText.length) {
        titleEl.textContent += titleText.charAt(i);
        i++;
      } else {
        window.clearInterval(this._titleTypingTimer);
        titleEl.innerHTML = titleHtml;
      }
    }, 25);
