  if (quoteEl) {
    const text = Model.translations[Model.locale].quote;
    quoteEl.textContent = "";
    let j = 0;
    this._quoteTypingTimer = window.setInterval(() => {
      if (j < text.length) {
        quoteEl.textContent += text.charAt(j);
        j++;
      } else {
        window.clearInterval(this._quoteTypingTimer);
